import 'dart:math' as math;import 'package:cloud_firestore/cloud_firestore.dart';import 'package:flutter/material.dart';import 'package:geolocator/geolocator.dart';import '../products/product_detail_screen.dart';class MarketplaceScreen extends StatefulWidget{const MarketplaceScreen({super.key});@override State<MarketplaceScreen> createState()=>_M();}class _M extends State<MarketplaceScreen>{Position? p;double radius=25;String q='';@override void initState(){super.initState();loc();}Future<void> loc()async{try{final z=await Geolocator.requestPermission();if(z!=LocationPermission.denied&&z!=LocationPermission.deniedForever){p=await Geolocator.getCurrentPosition();if(mounted)setState((){});}}catch(_){}}double km(double a,double b){if(p==null)return 999999;const r=6371.0;final dl=(a-p!.latitude)*math.pi/180,dd=(b-p!.longitude)*math.pi/180;final h=math.sin(dl/2)*math.sin(dl/2)+math.cos(p!.latitude*math.pi/180)*math.cos(a*math.pi/180)*math.sin(dd/2)*math.sin(dd/2);return r*2*math.atan2(math.sqrt(h),math.sqrt(1-h));}@override Widget build(BuildContext c)=>Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(onChanged:(v)=>setState(()=>q=v.toLowerCase()),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Cari barang...',filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.all(Radius.circular(16)),borderSide:BorderSide.none)))),Expanded(child:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('products').where('status',isEqualTo:'active').snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final a=s.data!.docs.where((d)=>(d.data()['title']??'').toString().toLowerCase().contains(q)).toList();a.sort((a,b){final x=a.data(),y=b.data();final dx=x['latitude'] is num?km((x['latitude'] as num).toDouble(),(x['longitude'] as num).toDouble()):999999;final dy=y['latitude'] is num?km((y['latitude'] as num).toDouble(),(y['longitude'] as num).toDouble()):999999;final tx=x['createdAt'] as Timestamp?,ty=y['createdAt'] as Timestamp?;final ax=dx<=radius?0:1,ay=dy<=radius?0:1;if(ax!=ay)return ax-ay;if((dx-dy).abs()>1)return dx.compareTo(dy);return (ty?.millisecondsSinceEpoch??0).compareTo(tx?.millisecondsSinceEpoch??0);});return ListView.builder(itemCount:a.length,itemBuilder:(c,i){final d=a[i],x=d.data();final dis=p!=null&&x['latitude'] is num?km((x['latitude'] as num).toDouble(),(x['longitude'] as num).toDouble()):null;return Card(margin:const EdgeInsets.symmetric(horizontal:12,vertical:6),child:ListTile(leading:x['imageUrl']?.toString().isNotEmpty==true?ClipRRect(borderRadius:BorderRadius.circular(12),child:Image.network(x['imageUrl'],width:64,height:64,fit:BoxFit.cover)):const Icon(Icons.inventory_2,size:40),title:Text(x['title']??''),subtitle:Text('Rp '+(x['price']??0).toString()+(dis==null?'':' • '+dis.toStringAsFixed(1)+' km')),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>ProductDetailScreen(productId:d.id))));});}))]);}}